        // node is the head
        head = node.next;
    }

    // Detach next node
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        // node is the tail
        tail = node.prev;
    }

    // If we removed the only element, clear head/tail
    if (head == null) {
        tail = null;
    }

    // Clean up removed node's links
    node.next = null;
    node.prev = null;

    // Update size counter
    size--;

